/**
 * Four things are checked before anything is written, and all four are
Component 1's `requireFamilyAuthorization`: the person holds the right
of final disposition, a director recorded which tier of C.R.S.
15-19-106 that was under, they typed their password rather than merely
holding a forwarded link, and the case is not marked disputed.

What is written is append-only and snapshots the answers as they stood
at the moment of signing. A correction is a second authorization.

On a tier that needs a majority, a second authorizing contact signing
the same document adds their own consent to the authorization already
recorded rather than opening a rival one. Nobody consents on anybody
else's behalf here — see `FamilyAuthorizationInput`.

 * @summary Sign an authorization
 */
export const getAuthorizeFamilyFormUrl = (caseFormId: number) => {
  return `/api/family/forms/${caseFormId}/authorize`;
};

export const authorizeFamilyForm = async (
  caseFormId: number,
  familyAuthorizationInput: FamilyAuthorizationInput,
  options?: RequestInit,
): Promise<CaseAuthorization> => {
  return customFetch<CaseAuthorization>(getAuthorizeFamilyFormUrl(caseFormId), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(familyAuthorizationInput),
  });
};

